use vstd::prelude::*;

verus! {

fn solve(t: Vec<char>) -> (out: Vec<char>)
    requires
        t.len() >= 1,
    ensures
        out.len() == t.len(),
        forall|i: int| 0 <= i < t.len() ==> out[i] == t[i],
{
    let n: usize = t.len();
    let mut out: Vec<char> = Vec::new();

    let mut i: usize = 0;

    while i < n
        invariant
            n == t.len(),
            0 <= i <= n,
            out.len() == i,
            // Already-constructed prefix matches the input
            forall|k: int| 0 <= k < i ==> out[k] == t[k],
        decreases
            n - i,
    {
        // We are about to append t[i] to out, so it remains a prefix copy.
        out.push(t[i]);

        i = i + 1;
    }

    out
}

} // verus!

